def parse_pairs(t_):
    import re
    txt_=t_
    # split into input/output sections
    parts=re.split(r'Demo pair \d+ (input|output)[^\n]*:', txt_)
    # safer: find labeled sections
    secs=re.findall(r'(input|output)\s*\((\d+)x(\d+)\):\n((?:\s*[0-2](?:\s+[0-2])*\n)+)', txt_)
    res=[]
    for i in range(0,len(secs)-1,2):
        if secs[i][0]=='input' and secs[i+1][0]=='output':
            gi=[[int(x) for x in row.split()] for row in secs[i][3].strip().split('\n')]
            go=[[int(x) for x in row.split()] for row in secs[i+1][3].strip().split('\n')]
            res.append((gi,go))
    return res
